import { SectionHeaderRule, SectionHeading, SiteSection } from "@/components/site/section";
import { UseCaseCodeTabs, UseCaseHowItWorks, UseCaseInstallCommand, UseCaseSectionLinks, UseCaseStepCards } from "@/components/site/use-case-how-it-works";

import { HOME_USE_CASES } from "./use-case-samples";

const SCRAPE = HOME_USE_CASES[0];

// One remembered language: picking a tab in the window also switches the install command beside it (and every other
// code sample on the page). The window carries the install command as its footer; the guides close the section.
export function CodeTabs() {
  return (
    <div className="flex w-full flex-col">
      <SiteSection lines>
        <SectionHeading title="Scrape any page," accent="in your language." />
        <SectionHeaderRule />
        <div className="grid grid-cols-1 items-center gap-10 lg:grid-cols-[minmax(0,20rem)_minmax(0,1fr)]">
          <UseCaseInstallCommand samples={SCRAPE.samples} />
          <UseCaseCodeTabs samples={SCRAPE.samples} showInstall label={SCRAPE.title} />
        </div>
        <UseCaseSectionLinks
          label="Guides for this workflow"
          links={[
            { label: "Scrape a page to Markdown", href: "https://docs.context.dev" },
            { label: "Crawl a whole site", href: "https://docs.context.dev/api-reference/batches/submit" },
          ]}
        />
      </SiteSection>
    </div>
  );
}

const TS = `import ContextDev from 'context.dev';

const client = new ContextDev({ apiKey: process.env.CONTEXT_DEV_API_KEY });

const crawl = await client.web.crawl({
  url: 'https://docs.stripe.com',
  maxPages: 500,
  formats: { markdown: true },
});

for (const page of crawl.pages) {
  console.log(page.url, page.markdown.length);
}`;

const PY = `from context_dev import ContextDev

client = ContextDev(api_key=os.environ["CONTEXT_DEV_API_KEY"])

crawl = client.web.crawl(
    url="https://docs.stripe.com",
    max_pages=500,
    formats={"markdown": True},
)

for page in crawl.pages:
    print(page.url, len(page.markdown))`;

const CURL = `curl https://api.context.dev/v1/web/crawl \\
  -H "Authorization: Bearer $CONTEXT_DEV_API_KEY" \\
  -d '{ "url": "https://docs.stripe.com", "maxPages": 500 }'`;

export function Site() {
  return (
    <div className="flex w-full flex-col">
      <SiteSection lines>
        <SectionHeading title="Crawl a site in" accent="three steps." description="Point it at a domain, choose the formats, and read every page back as clean Markdown." />
        <SectionHeaderRule />
        <UseCaseHowItWorks
          steps={[
            { title: "Get an API key", description: "Sign up and copy your key from the dashboard." },
            { title: "Start a crawl", description: "Send the start URL and how many pages to follow." },
            { title: "Read the pages", description: "Each page comes back as Markdown, HTML or JSON." },
          ]}
          samples={[
            { language: "typescript", label: "TypeScript", filename: "crawl.ts", code: TS, install: "npm install context.dev" },
            { language: "python", label: "Python", filename: "crawl.py", code: PY, install: "pip install context-dev" },
            { language: "curl", label: "cURL", filename: "crawl.sh", code: CURL, install: null },
          ]}
          docs={{ label: "Read the crawl docs", href: "https://docs.context.dev" }}
          note="Free to start: 1,000 credits a month, no card needed."
        />
      </SiteSection>

      <SiteSection lines>
        <SectionHeading title="From URL to" accent="answer." />
        <SectionHeaderRule />
        <UseCaseStepCards
          steps={[
            { title: "Search", description: "Find the pages that answer the question.", code: `const results = await client.web.search({\n  query: 'stripe usage based billing',\n});` },
            { title: "Scrape", description: "Read each result as Markdown.", code: `const page = await client.web.scrape({\n  url: results[0].url,\n  formats: { markdown: true },\n});` },
            { title: "Answer", description: "Hand the pages to your model with their sources.", code: `const answer = await model.generate({\n  context: page.markdown.data,\n});` },
          ]}
          links={[
            { label: "Search API", href: "https://context.dev/products/search" },
            { label: "Scrape API", href: "https://context.dev/products/scrape" },
          ]}
        />
      </SiteSection>
    </div>
  );
}

// The home page's use case samples, as context.dev shows them (production main 2f4c4559, marketing-api-examples.ts and
// product-code-samples.ts): every product in the six SDK languages. Shared by the use-cases and how-it-works examples.
import type { PersonaGlyphName } from "@/components/visuals/persona-glyph";
import type { UseCaseSample } from "@/components/site/use-case-how-it-works";

export type HomeUseCase = { id: string; title: string; description: string; glyph: PersonaGlyphName; docsUrl: string; samples: UseCaseSample[] };

export const HOME_USE_CASES: HomeUseCase[] = [
  {
    id: "scrape",
    title: "Scrape anything",
    description: "Get Markdown, HTML, screenshots, images, or structured fields from any URL.",
    glyph: "scrape",
    docsUrl: "https://docs.context.dev",
    samples: [
      { language: "typescript", label: "TypeScript", filename: "scrape.ts", install: "npm install context.dev", code: `import ContextDev from 'context.dev';

const client = new ContextDev({ apiKey: 'YOUR_API_KEY' });

const page = await client.web.scrape({
  url: 'https://linear.app',
  formats: {
    markdown: true,
    html: true,
    screenshot: true,
  },
  sharedParams: { mainContentOnly: true },
});

if (page.markdown.success) console.log(page.markdown.data);
if (page.screenshot.success) console.log(page.screenshot.data);` },
      { language: "python", label: "Python", filename: "scrape.py", install: "pip install context.dev", code: `from context.dev import ContextDev

client = ContextDev(api_key="YOUR_API_KEY")

response = client.web.scrape(
    url="https://linear.app",
    formats={
        "html": True,
        "markdown": True,
        "screenshot": True
    },
    shared_params={
        "main_content_only": True
    },
)
print(response)` },
      { language: "ruby", label: "Ruby", filename: "scrape.rb", install: "gem install context.dev base64", code: `require "cgi/core"
require "context_dev"

client = ContextDev::Client.new(api_key: "YOUR_API_KEY")

response = client.web.scrape(
  url: "https://linear.app",
  formats: {
    html: true,
    markdown: true,
    screenshot: true
  },
  shared_params: {
    main_content_only: true
  }
)
puts response` },
      { language: "php", label: "PHP", filename: "scrape.php", install: "composer require \"context-dev/context-dev-php:^2.24\" guzzlehttp/guzzle", code: `<?php

require_once 'vendor/autoload.php';

use ContextDev\\Client;

$client = new Client(apiKey: 'YOUR_API_KEY');

$response = $client->web->scrape(
    url: 'https://linear.app',
    formats: [
        'html' => true,
        'markdown' => true,
        'screenshot' => true
    ],
    sharedParams: [
        'mainContentOnly' => true
    ]
);

var_dump($response);` },
      { language: "go", label: "Go", filename: "scrape.go", install: "go get github.com/context-dot-dev/context-go-sdk/v2", code: `package main

import (
	"context"
	"fmt"

	contextdev "github.com/context-dot-dev/context-go-sdk/v2"
	"github.com/context-dot-dev/context-go-sdk/v2/option"
)

func main() {
	client := contextdev.NewClient(
		option.WithAPIKey("YOUR_API_KEY"),
	)

	response, err := client.Web.Scrape(context.TODO(), contextdev.WebScrapeParams{
		URL: "https://linear.app",
		Formats: contextdev.WebScrapeParamsFormats{
			HTML:       contextdev.Bool(true),
			Markdown:   contextdev.Bool(true),
			Screenshot: contextdev.Bool(true),
		},
		SharedParams: contextdev.WebScrapeParamsSharedParams{
			MainContentOnly: contextdev.Bool(true),
		},
	})
	if err != nil {
		panic(err)
	}

	fmt.Printf("%+v\\n", response)
}` },
      { language: "curl", label: "cURL", filename: "scrape.sh", install: null, code: `curl --request POST 'https://api.context.dev/v1/web/scrape' \\
  --header 'Authorization: Bearer YOUR_API_KEY' \\
  --header 'Content-Type: application/json' \\
  --data '{
  "url": "https://linear.app",
  "formats": {
    "html": true,
    "markdown": true,
    "screenshot": true
